-- =============================================
-- HotelManagement - PostgreSQL schema
-- Chuyển từ SQL Server:
--   IDENTITY      -> GENERATED BY DEFAULT AS IDENTITY
--   NVARCHAR(n)   -> VARCHAR(n)   (PG mặc định UTF8)
--   NVARCHAR(MAX) -> TEXT
--   BIT           -> BOOLEAN
--   DATETIME      -> TIMESTAMP
--   FLOAT (tiền)  -> NUMERIC(15,2)
-- Tên bảng/cột đổi sang snake_case (PG tự lowercase tên không quote)
-- =============================================

CREATE EXTENSION IF NOT EXISTS pgcrypto;

-- ============ DANH MỤC ĐỘC LẬP ============

CREATE TABLE roles (
    id        INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    role_name VARCHAR(50)
);

CREATE TABLE customer_types (
    id      INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    details VARCHAR(255)
);

CREATE TABLE room_types (
    id      INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    details VARCHAR(255)
);

CREATE TABLE room_status (
    id      INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    details VARCHAR(255)
);

CREATE TABLE service_types (
    id      INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    details VARCHAR(255)
);

CREATE TABLE vouchers (
    id              INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    voucher_code    VARCHAR(50),
    voucher_percent NUMERIC(5,2),
    date_start      DATE,
    date_end        DATE
);

CREATE TABLE payments (
    id              INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    payment_details VARCHAR(255)
);

-- ============ CẤP 1 ============

CREATE TABLE employees (
    id               INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    citizen_identity VARCHAR(20),
    fullname         VARCHAR(100),
    gender           VARCHAR(10),
    dob              DATE,
    address          VARCHAR(200),
    phone            VARCHAR(15),
    email            VARCHAR(50),
    avatar           VARCHAR(255),
    created_date     DATE,
    is_active        BOOLEAN,
    role_id          INT REFERENCES roles(id)
);

CREATE TABLE customers (
    id               INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    fullname         VARCHAR(100),
    citizen_identity VARCHAR(20),
    phone            VARCHAR(15),
    email            VARCHAR(50),
    dob              DATE,
    customer_type    INT REFERENCES customer_types(id)
);

CREATE TABLE rooms (
    id          INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    room_name   VARCHAR(50),
    price       NUMERIC(15,2),
    roomtype_id INT REFERENCES room_types(id),
    room_status INT REFERENCES room_status(id)
);

CREATE TABLE service_details (
    id                  INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name_service        VARCHAR(100),
    price               NUMERIC(15,2),
    service_code        VARCHAR(50),
    remaining_inventory INT,
    unit                VARCHAR(20),
    servicetype_id      INT REFERENCES service_types(id)
);

-- ============ CẤP 2 ============

CREATE TABLE accounts (
    username     VARCHAR(50) PRIMARY KEY,
    pass         VARCHAR(255),
    created_date TIMESTAMP,
    is_active    BOOLEAN,
    employee_id  INT REFERENCES employees(id)
);

CREATE TABLE lost_items (
    id             INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    item_name      VARCHAR(100),
    description    VARCHAR(255),
    date_found     TIMESTAMP,
    location_found VARCHAR(255),
    employee_id    INT REFERENCES employees(id),
    customer_id    INT REFERENCES customers(id),
    status         VARCHAR(50)
);

CREATE TABLE customer_groups (
    id          INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    customer_id INT REFERENCES customers(id)
);

CREATE TABLE inventory_receiving (
    id                INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    servicedetails_id INT REFERENCES service_details(id),
    quantity          INT,
    price             NUMERIC(15,2),
    in_date           TIMESTAMP
);

CREATE TABLE inventory_delivery (
    id                INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    servicedetails_id INT REFERENCES service_details(id),
    quantity          INT,
    out_date          TIMESTAMP
);

-- ============ CẤP 3 ============

CREATE TABLE authorities (
    username   VARCHAR(50) REFERENCES accounts(username),
    permission VARCHAR(50),
    details    VARCHAR(255),
    PRIMARY KEY (username, permission)
);

CREATE TABLE group_members (
    id           INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    fullname     VARCHAR(100),
    relationship VARCHAR(50),
    group_id     INT REFERENCES customer_groups(id)
);

CREATE TABLE bookings (
    id           INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    customer_id  INT REFERENCES customers(id),
    room_id      INT REFERENCES rooms(id),
    date_booking TIMESTAMP,
    date_start   TIMESTAMP,
    date_end     TIMESTAMP,
    deposits     NUMERIC(15,2),
    employee_id  INT REFERENCES employees(id),
    vouchers_id  INT REFERENCES vouchers(id)
);

-- ============ CẤP 4 & 5 ============

CREATE TABLE booking_histories (
    id               INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    citizen_identity VARCHAR(20),
    booking_id       INT REFERENCES bookings(id),
    date_start       TIMESTAMP,
    date_end         TIMESTAMP,
    total_payment    NUMERIC(15,2),
    special_request  VARCHAR(255),
    feedback         TEXT
);

CREATE TABLE invoices (
    id          INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    booking_id  INT REFERENCES bookings(id),
    issue_date  TIMESTAMP,
    employee_id INT REFERENCES employees(id),
    payment_id  INT REFERENCES payments(id)
);

CREATE TABLE invoice_details (
    id                INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    invoices_id       INT REFERENCES invoices(id),
    servicedetails_id INT REFERENCES service_details(id),
    quantity          INT,
    use_date          TIMESTAMP,
    vouchers_id       INT REFERENCES vouchers(id)
);
